import { forwardRef, Children, cloneElement, isValidElement } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { CircleProgress } from "@components/circle-progress";
import { CheckCircleSolid, SelectCircleArea, AttentionCircleSolid } from "@exp-textura/icons";

import { AITaskProps, AITaskListProps } from "./ai-task.types";
import { AITaskClasses, StyledAITask, AITaskListClasses, StyledAITaskList } from "./ai-task.styles";

export const AITask = forwardRef<HTMLDivElement, AITaskProps>(
  ({ className, children, state = "pending", variant = "default", styleSlots, ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(AITaskClasses.task, className);

    const renderIcon = () => {
      switch (state) {
        case "loading":
          return (
            <CircleProgress
              styleSlots={{
                indeterminate: {
                  width: theme.toRem(16),
                  height: theme.toRem(16),
                  ...styleSlots?.loader,
                },
                indeterminateCircle: {
                  strokeWidth: theme.toRem(4),
                  ...styleSlots?.loaderCircle,
                },
              }}
            />
          );
        case "completed":
          return <CheckCircleSolid />;
        case "error":
          return <AttentionCircleSolid />;
        case "pending":
        default:
          return <SelectCircleArea />;
      }
    };

    return (
      <StyledAITask
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        data-state={state}
        state={state}
        styleSlots={styleSlots}
        variant={variant}
        {...props}
      >
        <div aria-hidden="true" className={AITaskClasses.icon} data-state={state}>
          {renderIcon()}
        </div>
        <div>{children}</div>
      </StyledAITask>
    );
  },
);

AITask.displayName = "AI.Task";

export const AITaskList = forwardRef<HTMLDivElement, AITaskListProps>(
  ({ className, children, variant = "default", ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(AITaskListClasses.list, className);

    const childrenWithProps = Children.map(children, (child) => {
      if (isValidElement(child)) {
        return cloneElement(child as React.ReactElement, { role: "listitem" });
      }
      return child;
    });

    return (
      <StyledAITaskList
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        role="list"
        variant={variant}
        {...props}
      >
        {childrenWithProps}
      </StyledAITaskList>
    );
  },
);

AITaskList.displayName = "AI.TaskList";
